"""RoboPaint execution record. Camera-calibrated single-sweep acrylic painting."""
import sys,json,time,math
sys.path.insert(0,'/opt/tools')
import numpy as np
from PIL import Image
from rcb_client import Robot

class Painter:
 def __init__(self):
  self.r=Robot(); self.o=self.r.get_obs(cameras=[],video='none'); self.pos=np.array(self.o.meta['proprio']['now'][7:10]);self.quat=[0,1,0,0];self.rows=[];self.color=None
 def flush(self,cameras=[]):
  if not self.rows:return
  rows=self.rows;self.rows=[]
  for k in range(0,len(rows),180):
   chunk=rows[k:k+180]; before=self.r.status()
   try: out=self.r.submit('ee_pose',chunk,dt=.05,cameras=cameras,video='none')
   except Exception:
    status=self.r.wait_ready();
    if status['calls']==before['calls']:out=self.r.submit('ee_pose',chunk,dt=.05,cameras=cameras,video='none')
    else:out=self.r.get_obs(cameras=cameras,video='none')
   with open('/app/output/execution.jsonl','a') as f:f.write(json.dumps({'rows':chunk,'meta':out.meta})+'\n')
   if out.stopped or out.done: raise RuntimeError(str(out.meta))
  self.o=out
  return out
 def move(self,p,speed=.09,hold=0):
  p=np.array(p);n=max(1,int(np.ceil(np.linalg.norm(p-self.pos)/(speed*.05))))
  for a in np.linspace(0,1,n+1)[1:]:self.rows.append([*(self.pos+(p-self.pos)*a),*self.quat])
  self.pos=p
  for _ in range(round(hold/.05)):self.rows.append([*p,*self.quat])
 def dip(self,c):
  self.move([*self.pos[:2],.065],hold=.15)
  x=-.16+.03*(c%5);y=.145+.03*(c//5)
  self.move([x,y,.065],speed=.15);self.move([x,y,.025],speed=.05,hold=.4);self.move([x,y,.065],speed=.05,hold=.15);self.color=c
 def stroke_world(self,pts,depth):
  pts=np.array(pts); self.move([*self.pos[:2],.052],hold=.1);self.move([*pts[0],.052],speed=.15,hold=.15)
  self.move([*pts[0],.0202-depth],speed=.04,hold=.25)
  for p in pts[1:]:self.move([*p,.0202-depth],speed=.025)
  self.move([*pts[-1],.0202-depth],hold=.15)
  self.move([*pts[-1],.052],speed=.05,hold=.15)
 def park(self):
  self.move([*self.pos[:2],.08]);self.move([-.1,.21,.12],speed=.15,hold=.4);self.flush()
 def observe(self,name):
  o=self.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam'],depth=True);o.save('/app/output/'+name)
  for c,im in o.last.items():Image.fromarray(im).save('/app/output/'+name+'_'+c+'.png')
  return o

if __name__=='__main__':
